/* @lc app=leetcode id=3786 lang=kotlin */ class Solution { fun interactionCosts(n: Int, edges: Array<IntArray>, group: IntArray): Long = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { order -> IntArray(n * 21).also { c -> (0 until n).forEach { c[it * 21 + group[it]]++ } }.also { c -> order.reversed().forEach { v -> if (v != 0) (1..20).forEach { gg -> c[par[v] * 21 + gg] += c[v * 21 + gg] } } }.let { c -> (1..20).sumOf { gg -> (c[gg]).let { tot -> (1 until n).sumOf { v -> c[v * 21 + gg].toLong() * (tot - c[v * 21 + gg]) } } } } } } } }